CREATE TABLE `sys_ai_channel` (
  `id` varchar(36) COLLATE utf8mb4_general_ci NOT NULL COMMENT '主键',
  `name` varchar(100) COLLATE utf8mb4_general_ci NOT NULL COMMENT '渠道名称',
  `channel_type` varchar(20) COLLATE utf8mb4_general_ci NOT NULL DEFAULT 'h5' COMMENT '类型：h5',
  `brand_name` varchar(100) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '品牌名',
  `avatar` varchar(500) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '品牌头像(URL)',
  `welcome` varchar(500) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '欢迎语',
  `disclaimer` varchar(500) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '免责声明',
  `allowed_domains` text COLLATE utf8mb4_general_ci COMMENT '允许嵌入域名(JSON 数组，空=不限制)',
  `tool_keys` text COLLATE utf8mb4_general_ci COMMENT 'H5 可用工具白名单(JSON 数组，tool_key 列表；只读、只查本人)',
  `theme_color` varchar(20) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '主题色(如 #1677ff)',
  `rate_limit` int DEFAULT NULL COMMENT '限流(次/分钟/访客，空=不限)',
  `status` varchar(20) COLLATE utf8mb4_general_ci NOT NULL DEFAULT 'active' COMMENT '状态：active启用/disabled停用',
  `is_del` int DEFAULT '0' COMMENT '删除标识：0未删除，1已删除',
  `create_by` varchar(36) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '创建人',
  `create_date` datetime DEFAULT NULL COMMENT '创建时间',
  `update_by` varchar(36) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '更新人',
  `update_date` datetime DEFAULT NULL COMMENT '更新时间',
  `remarks` varchar(500) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '备注',
  PRIMARY KEY (`id`) USING BTREE,
  KEY `idx_channel_status` (`status`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='AI H5 渠道/品牌配置';
