  `query` varchar(500) COLLATE utf8mb4_general_ci NOT NULL COMMENT '检索词',
  `hit_count` int DEFAULT '0' COMMENT '命中数',
  `citations` longtext COLLATE utf8mb4_general_ci COMMENT '引用(JSON：文档/标题/版本/块序号)',
  `cost_ms` int DEFAULT NULL COMMENT '耗时(ms)',
