CREATE TABLE `sys_ai_tool` (
  `id` varchar(36) COLLATE utf8mb4_general_ci NOT NULL COMMENT '主键',
  `tool_key` varchar(64) COLLATE utf8mb4_general_ci NOT NULL COMMENT '工具标识（唯一，模型据此选择）',
  `name` varchar(100) COLLATE utf8mb4_general_ci NOT NULL COMMENT '工具名称',
  `method` varchar(10) COLLATE utf8mb4_general_ci NOT NULL DEFAULT 'GET' COMMENT 'HTTP 方法：GET/POST',
  `path` varchar(255) COLLATE utf8mb4_general_ci NOT NULL COMMENT 'magic-api 接口路径',
  `description` text COLLATE utf8mb4_general_ci COMMENT '给模型看的接口说明（用途/入参/返回含义）',
  `params_schema` longtext COLLATE utf8mb4_general_ci COMMENT '入参 JSON Schema',
  `response_schema` longtext COLLATE utf8mb4_general_ci COMMENT '返回结构说明（字段/含义）',
  `required_permission` varchar(100) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '调用所需权限码',
  `scope_type` varchar(10) COLLATE utf8mb4_general_ci NOT NULL DEFAULT 'self' COMMENT '数据范围：self/org/all',
  `sensitive_fields` varchar(500) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '需脱敏字段（逗号分隔）',
  `read_only` tinyint(1) NOT NULL DEFAULT '1' COMMENT '是否只读：1只读，0可写',
  `enabled` tinyint(1) NOT NULL DEFAULT '1' COMMENT '是否启用：0停用，1启用',
  `is_del` int DEFAULT '0' COMMENT '删除标识：0未删除，1已删除',
  `create_by` varchar(36) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '创建人',
  `create_date` datetime DEFAULT NULL COMMENT '创建时间',
  `update_by` varchar(36) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '更新人',
  `update_date` datetime DEFAULT NULL COMMENT '更新时间',
  `remarks` text COLLATE utf8mb4_general_ci COMMENT '备注',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE KEY `uk_tool_key` (`tool_key`),
  KEY `idx_enabled` (`enabled`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='AI 工具目录';
