INSERT INTO `sys_ai_tool` VALUES
('a1000000-0000-4000-8000-000000000001','order_list','订单列表','GET','/business/order/list','查询订单列表，支持按客户名称/订单状态/订单号过滤，分页返回。用于回答“某客户有哪些订单/某状态订单/订单金额”类问题。','{\"type\":\"object\",\"properties\":{\"customerName\":{\"type\":\"string\",\"description\":\"客户名称\"},\"status\":{\"type\":\"string\",\"description\":\"订单状态：待付款/已付款/已完成/已取消\"},\"orderNo\":{\"type\":\"string\",\"description\":\"订单号\"},\"page\":{\"type\":\"integer\",\"description\":\"页码\"},\"size\":{\"type\":\"integer\",\"description\":\"每页条数\"}}}','返回 {records:[{id,order_no,amount,status,create_date,customer_name}], total}',NULL,'all',NULL,1,1,0,'system','2026-11-05 18:34:14',NULL,NULL,'2.0 试点：只读订单查询'),
('a1000000-0000-4000-8000-000000000002','customer_detail','客户详情','GET','/business/customer/detail','按客户ID或客户名称查询客户详情，含联系人/电话/等级/订单数/累计金额。用于回答“某客户信息/某客户消费情况”类问题。','{\"type\":\"object\",\"properties\":{\"id\":{\"type\":\"string\",\"description\":\"客户ID\"},\"name\":{\"type\":\"string\",\"description\":\"客户名称\"}}}','返回 {id,name,contact,phone,level,create_date,order_count,total_amount}',NULL,'all','phone',1,1,0,'system','2026-11-05 18:34:14',NULL,NULL,'2.0 试点：只读客户查询');
