  `status` varchar(20) COLLATE utf8mb4_general_ci NOT NULL DEFAULT 'success' COMMENT '结果：success/no_data/not_found/no_permission/tool_error/timeout',
  `row_count` int DEFAULT NULL COMMENT '返回行数',
