px 12px rgba(0,0,0,0.08);\n    border-color: rgba(45,140,240,0.2);\n}\n.msg-card.unread[data-v-6a44f8a5dfa44afe9a77f7231686a821] {\n    background: linear-gradient(to right, rgba(45,140,240,0.04), #fff 30%);\n    border-left: 3px solid #f56c6c;\n}\n.msg-card-side[data-v-6a44f8a5dfa44afe9a77f7231686a821] {\n    flex-shrink: 0;\n    width: 40px;\n    height: 40px;\n    display: flex;\n    align-items: center;\n    justify-content: center;\n    background: var(--surface-soft, #f5f7fa);\n    border-radius: 50%;\n    margin-top: 2px;\n}\n.msg-card-body[data-v-6a44f8a5dfa44afe9a77f7231686a821] {\n    flex: 1;\n    min-width: 0;\n}\n.msg-card-head[data-v-6a44f8a5dfa44afe9a77f7231686a821] {\n    display: flex;\n    align-items: center;\n    gap: 8px;\n    margin-bottom: 6px;\n}\n.msg-card-title[data-v-6a44f8a5dfa44afe9a77f7231686a821] {\n    font-size: 15px;\n    font-weight: 500;\n    color: #222;\n    display: flex;\n    align-items: center;\n    gap: 6px;\n    min-width: 0;\n    flex: 1;\n}\n.msg-dot[data-v-6a44f8a5dfa44afe9a77f7231686a821] {\n    display: inline-block;\n    width: 8px;\n    height: 8px;\n    border-radius: 50%;\n    background: #f56c6c;\n    flex-shrink: 0;\n}\n.msg-card.unread .msg-card-title[data-v-6a44f8a5dfa44afe9a77f7231686a821] {\n    font-weight: 600;\n    color: #111;\n}\n.msg-card-content[data-v-6a44f8a5dfa44afe9a77f7231686a821] {\n    color: #555;\n    font-size: 13px;\n    line-height: 1.6;\n    margin-bottom: 8px;\n    word-break: break-word;\n}\n.msg-card-meta[data-v-6a44f8a5dfa44afe9a77f7231686a821] {\n    display: flex;\n    flex-wrap: wrap;\n    gap: 14px;\n    color: #999;\n    font-size: 12px;\n}\n.msg-meta-item[data-v-6a44f8a5dfa44afe9a77f7231686a821] {\n    display: inline-flex;\n    align-items: center;\n    gap: 4px;\n}\n.msg-unread-tag[data-v-6a44f8a5dfa44afe9a77f7231686a821] {\n    color: #f56c6c;\n}\n.msg-card-actions[data-v-6a44f8a5dfa44afe9a77f7231686a821] {\n    flex-shrink: 0;\n    display: flex;\n    flex-direction: column;