('36bc0e73-9b1b-4875-89be-9e96c1619bf7','29d82244-d928-11ee-9675-c2b02332sd','openapi-request-log','<template>\n  <div class=\"mb-list\">\n    <div class=\"mb-search\">\n      <n-space align=\"center\" wrap>\n        <n-select v-model:value=\"filterAppId\" :options=\"appOptions\" placeholder=\"选择应用\" clearable style=\"width:220px\" />\n        <n-input v-model:value=\"filterApiPath\" placeholder=\"接口路径（模糊）\" clearable style=\"width:220px\" @keyup.enter=\"doSearch\" />\n        <n-select v-model:value=\"filterApiMethod\" :options=\"methodOptions\" placeholder=\"HTTP 方法\" clearable style=\"width:130px\" />\n        <n-select v-model:value=\"filterStatus\" :options=\"statusOptions\" placeholder=\"请求状态\" clearable style=\"width:140px\" />\n        <n-date-picker\n          v-model:value=\"filterDateRange\"\n          type=\"datetimerange\"\n          clearable\n          style=\"width:340px\"\n          placeholder=\"请求时间范围\"\n        />\n        <n-button type=\"primary\" @click=\"doSearch\">\n          <mb-icon icon=\"Search\" /> 查询\n        </n-button>\n        <n-button @click=\"doReset\">\n          <mb-icon icon=\"Refresh\" /> 重置\n        </n-button>\n      </n-space>\n    </div>\n    <div class=\"mb-table\">\n      <mb-table ref=\"table\" v-bind=\"tableOptions\" />\n    </div>\n  </div>\n</template>\n\n<script setup>\nimport { ref, reactive, onMounted } from \'vue\'\n\nconst appOptions = ref([])\nconst filterAppId = ref(null)\nconst filterApiPath = ref(\'\')\nconst filterApiMethod = ref(null)\nconst filterStatus = ref(null)\nconst filterDateRange = ref(null)\n\nconst methodOptions = [\n  { label: \'GET\', value: \'GET\' },\n  { label: \'POST\', value: \'POST\' },\n  { label: \'PUT\', value: \'PUT\' },\n  { label: \'DELETE\', value: \'DELETE\' }\n]\n\nconst statusOptions = [\n  { label: \'成功\', value: \'success\' },\n  { label: \'失败\', value: \'fail\' }\n]\n\nconst tableOptions = reactive({\n  id: \'open-request-log\',\n  url: \'/system/open/app/request-log\',\n  