('7342c275-29db-4849-80bb-10d3bcc4485a','0','dashboard','<template>\n    <div class=\"dashboard-wrap\">\n        <!-- 统计卡片 -->\n        <div class=\"dash-stats\">\n            <div class=\"stat-card\" v-for=\"s in statCards\" :key=\"s.key\">\n                <div class=\"stat-icon\" :style=\"{ background: s.bg }\">\n                    <mb-icon :icon=\"s.icon\" size=\"30px\" :color=\"s.color\" />\n                </div>\n                <div class=\"stat-info\">\n                    <div class=\"stat-value\">{{ s.value }}</div>\n                    <div class=\"stat-label\">{{ s.label }}</div>\n                </div>\n                <div class=\"stat-line\" :style=\"{ background: s.color }\"></div>\n            </div>\n        </div>\n\n        <!-- 图表区 -->\n        <div class=\"dash-charts\">\n            <n-card class=\"panel-card\" size=\"small\">\n                <template #header>\n                    <div class=\"panel-title\"><mb-icon icon=\"BarChartOutline\" size=\"18px\" color=\"#2D8CF0\" />近12个月销售趋势（万元）</div>\n                </template>\n                <div ref=\"trendEl\" class=\"chart-box\"></div>\n            </n-card>\n            <n-card class=\"panel-card\" size=\"small\">\n                <template #header>\n                    <div class=\"panel-title\"><mb-icon icon=\"PieChartOutline\" size=\"18px\" color=\"#fa8c16\" />品类销售额占比</div>\n                </template>\n                <div ref=\"pieEl\" class=\"chart-box\"></div>\n            </n-card>\n        </div>\n\n        <!-- 表格区 -->\n        <div class=\"dash-tables\">\n            <n-card class=\"panel-card\" size=\"small\">\n                <template #header>\n                    <div class=\"panel-title\"><mb-icon icon=\"DocumentTextOutline\" size=\"18px\" color=\"#722ed1\" />最近操作日志</div>\n                </template>\n                <n-table size=\"small\" :bordered=\"false\" :single-line=\"false\">\n                    <thead>\n                        <tr>\n                            <th>接口名称</th>\n                            <th>方式</th>\n                            <th>耗时</th>\n                            <th>操作人</th>\n                            <th>时间</th>\n                        </tr>\n                    </thead>\n                    <tbody>\n                        <tr v-for=\"r in operLogs\" :key=\"r.id\">\n                            <td class=\"ellipsis\" :title=\"r.apiPath\">{{ r.apiName }}</td>\n                            <td><n-tag size=\"small\" :type=\"methodType(r.apiMethod)\" :bordered=\"false\">{{ r.apiMethod }}</n-tag></td>\n                            <td>{{ r.costTime }}ms</td>\n                            <td>{{ r.createBy }}</td>\n                            <td>{{ r.createDate }}</td>\n                        </tr>\n                        <tr v-if=\"!operLogs.length\">\n                            <td colspan=\"5\" class=\"empty-cell\">暂无数据</td>\n                        </tr>\n                    </tbody>\n                </n-table>\n            </n-card>\n            <n-card class=\"panel-card\" size=\"small\">\n                <template #header>\n                    <div class=\"panel-title\"><mb-icon icon=\"PeopleOutline\" size=\"18px\" color=\"#52c41a\" />最近登录日志</div>\n                </template>\n                <n-table size=\"small\" :bordered=\"false\" :single-line=\"false\">\n                    <thead>\n                        <tr>\n                            <th>账号</th>\n                            <th>IP</th>\n                            <th>浏览器</th>\n                            <th>状态</th>\n                            <th>时间</th>\n                        </tr>\n                    </thead>\n                    <tbody>\n                        <tr v-for=\"r in loginLogs\" :key=\"r.id\">\n                            <td>{{ r.username }}</td>\n                            <td>{{ r.ip }}</td>\n                            <td class=\"ellipsis\" :title=\"r.browser\">{{ r.browser }}</td>\n                            <td>\n                                <n-tag size=\"small\" :type=\"r.type === \'成功\' ? \'success\' : \'error\'\" :bordered=\"false\">{{ r.type }}</n-tag>\n                            </td>\n                            <td>{{ r.createDate }}</td>\n                        </tr>\n                        <tr v-if=\"!loginLogs.length\">\n                            <td colspan=\"5\" class=\"empty-cell\">暂无数据</td>\n                        </tr>\n                    </tbody>\n                </n-table>\n            </n-card>\n        </div>\n    </div>\n</template>\n\n<script setup>\nimport { ref, reactive, onMounted, onBeforeUnmount, nextTick } from \'vue\'\nimport { init as echartsInit } from \'echarts\'\n\nconst trendEl = ref(null)\nconst pieEl = ref(null)\nlet trendChart = null\nlet pieChart = null\n\nconst statCards = reactive([\n    { key: \'users\', label: \'用户总数\', value: 0, icon: \'PeopleOutline\', color: \'#2D8CF0\', bg: \'rgba(45,140,240,0.12)\' },\n    { key: \'roles\', label: \'角色总数\', value: 0, icon: \'ShieldCheckmarkOutline\', color: \'#52c41a\', bg: \'rgba(82,196,26,0.12)\' },\n    { key: \'menus\', label: \'菜单数量\', value: 0, icon: \'Menu\', color: \'#fa8c16\', bg: \'rgba(250,140,22,0.12)\' },\n    { key: \'logs\', label: \'操作日志\', value: 0, icon: \'AnalyticsOutline\', color: \'#722ed1\', bg: \'rgba(114,46,209,0.12)\' }\n])\n\nconst operLogs = ref([])\nconst loginLogs = ref([])\n\nfunction methodType(m) {\n    if (m === \'POST\') return \'primary\'\n    if (m === \'GET\') return \'success\'\n    if (m === \'PUT\' || m === \'DELETE\') return \'warning\'\n    return \'default\'\n}\n\nasync function loadStats() {\n    try {\n        const [users, roles, oper] = await Promise.all([\n            $common.post(\'/system/user/list\', { current: 1, size: 1 }),\n            $common.post(\'/system/role/list\', { current: 1, size: 1 }),\n            $common.post(\'/system/log/oper/list\', { current: 1, size: 1 })\n        ])\n        statCards[0].value = users?.data?.total || 0\n        statCards[1].value = roles?.data?.total || 0\n        statCards[3].value = oper?.data?.total || 0\n        const menus = await $common.post(\'/system/menu/current/menus\')\n        const lm = menus?.data?.layoutMenus || []\n        const countMenu = (list) => {\n            let n = 0\n            for (const m of list) {\n                n++\n                if (m.children) n += countMenu(m.children)\n            }\n            return n\n        }\n        statCards[2].value = countMenu(lm)\n    } catch (e) {\n        console.warn(\'[dashboard] stats load failed\', e)\n    }\n}\n\nasync function loadLogs() {\n    try {\n        const [oper, login] = await Promise.all([\n            $common.post(\'/system/log/oper/list\', { current: 1, size: 6 }),\n            $common.post(\'/system/log/login/list\', { current: 1, size: 6 })\n        ])\n        operLogs.value = oper?.data?.list || []\n        loginLogs.value = login?.data?.list || []\n    } catch (e) {\n        console.warn(\'[dashboard] logs load failed\', e)\n    }\n}\n\nfunction waitForSize(el, timeout = 2000) {\n    return new Promise((resolve) => {\n        const check = () => {\n            if (el && el.clientWidth > 0 && el.clientHeight > 0) {\n                resolve()\n            } else if (timeout <= 0) {\n                resolve()\n            } else {\n                timeout -= 50\n                setTimeout(check, 50)\n            }\n        }\n        check()\n    })\n}\n\nasync function loadTrend() {\n    try {\n        const res = await $common.post(\'/data/report-op/sales-trend\')\n        const rows = res?.data || []\n        if (!rows.length) return\n        await waitForSize(trendEl.value)\n        const months = [\'1月\', \'2月\', \'3月\', \'4月\', \'5月\', \'6月\', \'7月\', \'8月\', \'9月\', \'10月\', \'11月\', \'12月\']\n        const keys = [\'m01\', \'m02\', \'m03\', \'m04\', \'m05\', \'m06\', \'m07\', \'m08\', \'m09\', \'m10\', \'m11\', \'m12\']\n        const series = rows.slice(