ementVNode(\"div\", {\n            ref_key: \"pieEl\",\n            ref: pieEl,\n            class: \"chart-box\"\n          }, null, 512 /* NEED_PATCH */)\n        ]),\n        _: 1 /* STABLE */\n      })\n    ]),\n    _createCommentVNode(\" 表格区 \"),\n    _createElementVNode(\"div\", _hoisted_9, [\n      _createVNode(_component_n_card, {\n        class: \"panel-card\",\n        size: \"small\"\n      }, {\n        header: _withCtx(() => [\n          _createElementVNode(\"div\", _hoisted_10, [\n            _createVNode(_component_mb_icon, {\n              icon: \"DocumentTextOutline\",\n              size: \"18px\",\n              color: \"#722ed1\"\n            }),\n            _createTextVNode(\"最近操作日志\")\n          ])\n        ]),\n        default: _withCtx(() => [\n          _createVNode(_component_n_table, {\n            size: \"small\",\n            bordered: false,\n            \"single-line\": false\n          }, {\n            default: _withCtx(() => [\n              _hoisted_11,\n              _createElementVNode(\"tbody\", null, [\n                (_openBlock(true), _createElementBlock(_Fragment, null, _renderList(operLogs.value, (r) => {\n                  return (_openBlock(), _createElementBlock(\"tr\", {\n                    key: r.id\n                  }, [\n                    _createElementVNode(\"td\", {\n                      class: \"ellipsis\",\n                      title: r.apiPath\n                    }, _toDisplayString(r.apiName), 9 /* TEXT, PROPS */, _hoisted_12),\n                    _createElementVNode(\"td\", null, [\n                      _createVNode(_component_n_tag, {\n                        size: \"small\",\n                        type: methodType(r.apiMethod),\n                        bordered: false\n                      }, {\n                        default: _withCtx(() => [\n                          _createTextVNode(_toDisplayString(r.apiMethod), 1 /* TEXT */)\n                        ]),\n                        _: 2 /* D