                  _createElementVNode(\"td\", {\n                      class: \"ellipsis\",\n                      title: r.browser\n                    }, _toDisplayString(r.browser), 9 /* TEXT, PROPS */, _hoisted_18),\n                    _createElementVNode(\"td\", null, [\n                      _createVNode(_component_n_tag, {\n                        size: \"small\",\n                        type: r.type === \'成功\' ? \'success\' : \'error\',\n                        bordered: false\n                      }, {\n                        default: _withCtx(() => [\n                          _createTextVNode(_toDisplayString(r.type), 1 /* TEXT */)\n                        ]),\n                        _: 2 /* DYNAMIC */\n                      }, 1032 /* PROPS, DYNAMIC_SLOTS */, [\"type\"])\n                    ]),\n                    _createElementVNode(\"td\", null, _toDisplayString(r.createDate), 1 /* TEXT */)\n                  ]))\n                }), 128 /* KEYED_FRAGMENT */)),\n                (!loginLogs.value.length)\n                  ? (_openBlock(), _createElementBlock(\"tr\", _hoisted_19, [..._hoisted_21]))\n                  : _createCommentVNode(\"v-if\", true)\n              ])\n            ]),\n            _: 1 /* STABLE */\n          })\n        ]),\n        _: 1 /* STABLE */\n      })\n    ])\n  ]))\n}\n}\n\n}\n__sfc__.__scopeId = \"data-v-43347d617a324760b87c9c783da82783\"\n__sfc__.__file = \"43347d617a324760b87c9c783da82783.vue\"\nreturn __sfc__','.dashboard-wrap[data-v-43347d617a324760b87c9c783da82783] {\n    padding: 16px;\n    display: flex;\n    flex-direction: column;\n    gap: 16px;\n    background: #f5f7fa;\n    min-height: 100%;\n    box-sizing: border-box;\n}\n.dash-stats[data-v-43347d617a324760b87c9c783da82783] {\n    display: grid;\n    grid-template-columns: repeat(4, 1fr);\n    gap: 16px;\n}\n.stat-card[data-v-43347d617a324760b87c9c783da82783] {\n    position: relative;\n    display: flex;\n    align-items: center;\n    gap: 16px;\n    padding: 20px;\n    border-radius: 12px;\n    background: #fff;\n    box-shadow: 0 2px 8px rgba(0, 0, 0, 0.06);\n    overflow: hidden;\n    transition: transform 0.2s, box-shadow 0.2s;\n}\n.stat-card[data-v-43347d617a324760b87c9c783da82783]:hover {\n    transform: translateY(-3px);\n    box-shadow: 0 6px 16px rgba(0, 0, 0, 0.1);\n}\n.stat-icon[data-v-43347d617a324760b87c9c783da82783] {\n    width: 54px;\n    height: 54px;\n    border-radius: 12px;\n    display: flex;\n    align-items: center;\n    justify-content: center;\n    flex-shrink: 0;\n}\n.stat-info[data-v-43347d617a324760b87c9c783da82783] {\n    flex: 1;\n    min-width: 0;\n}\n.stat-value[data-v-43347d617a324760b87c9c783da82783] {\n    font-size: 28px;\n    font-weight: 700;\n    line-height: 1.1;\n    color: #213547;\n}\n.stat-label[data-v-43347d617a324760b87c9c783da82783] {\n    margin-top: 6px;\n    font-size: 13px;\n    color: #909399;\n}\n.stat-line[data-v-43347d617a324760b87c9c783da82783] {\n    position: absolute;\n    left: 0;\n    top: 0;\n    bottom: 0;\n    width: 4px;\n}\n.dash-charts[data-v-43347d617a324760b87c9c783da82783] {\n    display: grid;\n    grid-template-columns: 3fr 2fr;\n    gap: 16px;\n}\n.panel-card[data-v-43347d617a324760b87c9c783da82783] {\n    border-radius: 12px;\n    box-shadow: 0 2px 8px rgba(0, 0, 0, 0.06);\n    border: none;\n}\n.panel-title[data-v-43347d617a324760b87c9c783da82783] {\n    display: flex;\n    align-items: center;\n    gap: 6px;\n    font-weight: 600;\n    color: #213547;\n}\n.chart-box[data-v-43347d617a324760b87c9c783da82783] {\n    height: 300px;\n    width: 100%;\n}\n.dash-tables[data-v-43347d617a324760b87c9c783da82783] {\n    display: grid;\n    grid-template-columns: 1fr 1fr;\n    gap: 16px;\n}\n.ellipsis[data-v-43347d617a324760b87c9c783da82783] {\n    max-width: 220px;\n    overflow: hidden;\n    text-overflow: ellipsis;\n    white-space: nowrap;\n}\n.empty-cell[data-v-43347d617a324760b87c9c783da82783] {\n    text-align: center;\n    color: #bbb;\n    padding: 24px 0;\n}\n@media (max-width: 900px) {\n.dash-stats[data-v-43347d617a324760b87c9c783da82783], .dash-charts[data-v-43347d617a324760b87c9c783da82783], .dash-tables[data-v-43347d617a324760b87c9c783da82783] {\n        grid-template-columns: 1fr;\n}\n}',1,NULL,0,'admin','2026-08-03 18:02:08',NULL,'2026-08-03 18:21:57'),
('7b04038d109b4946a844b66f19126597','29d82244-d928-11ee-9675-c2b02ed3977b','configure',NULL,NULL,NULL,0,'',0,'1','2026-08-04 10:14:33',NULL,NULL),
('7f6aa6e5-9122-44ce-affc-555020f88a34','99a517159abd4eb4aca9eb4d5f5c6c19','menu-icon-list','<template>\n    <div class=\"menu-icon-list page-container\">\n        <n-card :bordered=\"false\" class=\"mb-4\">\n            <n-alert type=\"info\" :show-icon=\"false\" class=\"mb-4\" style=\"font-size: 13px\">\n                <div class=\"help-line\">支持两种方式添加图标：</div>\n                <div class=\"help-line\">① <b>上传图标</b>：选择本地图片（png / jpeg / gif / svg / webp / ico，单文件 ≤2MB），可多选批量上传，自动保存到 /userfiles 静态资源。</div>\n                <div class=\"help-line\">② <b>导入 iconfont 符号</b>：在 <a href=\"https://www.iconfont.cn\" target=\"_blank\">iconfont.cn</a>（阿里图标库）「Symbol」模式导出的 <code>iconfont.js</code> 或含多个 <code>&lt;symbol&gt;</code> 的 <code>.svg</code> 文件，自动解析全部符号入库。</div>\n                <div class=\"help-line\">添加后在菜单/模块的图标选择器「上传的图标」页签中选择，或双击卡片复制图标值。</div>\n            </n-alert>\n            <div class=\"flex items-center justify-between flex-wrap gap-3\">\n                <n-space align=\"center\">\n                    <n-input\n                        v-model:value=\"keyword\"\n                        placeholder=\"搜索图标名称 / 值...\"\n                        clearable\n                        style=\"width: 240px\"\n                        @keydown.enter=\"loadUploaded\"\n                    >\n                        <template #prefix>\n                            <mb-icon icon=\"SearchOutline\" size=\"14px\" />\n                        </template>\n                    </n-input>\n                    <n-button size=\"small\" type=\"primary\" ghost @click=\"loadUploaded\">搜索</n-button>\n                </n-space>\n                <n-upload\n                    :show-file-list=\"false\"\n                    multiple\n                    accept=\"image/png,image/jpeg,image/gif,image/svg+xml,image/webp,image/x-icon\"\n                    :before-upload=\"onBeforeUpload\"\n                    @change=\"onUploadChange\"\n                >\n                    <n-button type=\"primary\">\n                        <template #icon>\n                            <mb-icon icon=\"AddOutline\" size=\"16px\" />\n                        </template>\n                        上传图标\n                    </n-button>\n                </n-upload>\n                <n-upload\n                    :show-file-list=\"false\"\n                    accept=\".js,.svg,.txt\"\n                    :before-upload=\"onBeforeImport\"\n                    @change=\"onIconfontImport\"\n                >\n                    <n-button secondary>\n                        <template #icon>\n                            <mb-icon icon=\"FolderOpenOutline\" size=\"16px\" />\n                        </template>\n                        导入 iconfont 符号\n                    </n-button>\n                </n-upload>\n            </div>\n        </n-card>\n\n        <n-tabs type=\"line\" animated>\n            <n-tab-pane name=\"uploaded\" tab=\"上传的图标\">\n                <div class=\"icon-grid\">\n                    <div v-for=\"item in uploadedList\" :key=\"item.id\" class=\"icon-card\" @dblclick=\"copyValue(item)\">\n                        <mb-icon :icon=\"item.iconValue\" size=\"2.2em\" />\n                        <div class=\"icon-name\">{{ item.iconName || \'(未命名)\' }}</div>\n                        <div class=\"icon-actions\">\n                            <n-button size=\"tiny\" quaternary @click=\"copyValue(item)\">\n                                <template #icon><mb-icon icon=\"CopyOutline\" size=\"13px\" /></template>\n                                复制\n                            </n-button>\n                            <n-button size=\"tiny\" quaternary type=\"error\" @click=\"removeIcon(item)\">\n                                <template #icon><mb-icon icon=\"TrashOutline\" size=\"13px\" /></template>\n                                删除\n                            </n-button>\n                        </div>\n                    </div>\n                    <n-empty v-if=\"!loading && uploadedList.length === 0\" description=\"还没有上传图标\" style=\"grid-column: 1 / -1; padding: 40px 0\" />\n                </div>\n            </n-tab-pane>\n\n            <n-tab-pane name=\"builtin\" tab=\"内置图标\">\n                <div class=\"icon-grid\">\n                    <div v-for=\"icon in builtinIcons\" :key=\"icon\" class=\"icon-card\" @dblclick=\"copyText(icon)\">\n                        <mb-icon :icon=\"icon\" size=\"2.2em\" />\n                        <div class=\"icon-name\">{{ icon }}</div>\n                        <div class=\"icon-actions\">\n                            <n-button size=\"tiny\" quaternary @click=\"copyText(icon)\">\n                                <template #icon><mb-icon icon=\"CopyOutline\" size=\"13px\" /></template>\n                                复制\n                            </n-button>\n                        </div>\n                    </div>\n                </div>\n            </n-tab-pane>\n        </n-tabs>\n    </div>\n</template>\n\n<script setup>\nimport { ref, computed, onMounted } from \'vue\'\nimport svgIcons from \'@/scripts/svg-icons\'\nimport xicons from \'@/scripts/xicons\'\nimport { bumpIcons } from \'@/scripts/icon-store\'\nimport { useDialog, useMessage } from \'naive-ui\'\n\nconst $message = useMessage()\nconst $dialog = useDialog()\n\nconst keyword = ref(\'\')\nconst uploadedList = ref([])\nconst loading = ref(false)\nlet processedIds = new Set()\n\nconst builtinIcons = computed(() => {\n    const names = [...svgIcons, ...Object.keys(xicons)]\n    const kw = keyword.value.trim().toLowerCase()\n    if (!kw) return names\n    return names.filter(n => n.toLowerCase().includes(kw))\n})\n\nfunction loadUploaded() {\n    loading.value = true\n    $common.post(\'/system/menu-icon/list\', {\n        current: 1,\n        size: 1000,\n        iconName: keyword.value.trim() || undefined\n    }).then(res => {\n        uploadedList.value = (res.data?.list || res.data?.records || []).map(it => ({\n            ...it,\n            iconValue: it.iconValue || \'\'\n        }))\n    }).catch(() => {\n        uploadedList.value = []\n    }).finally(() => {\n        loading.value = false\n    })\n}\n\nasync function readFileAsBase64(blob) {\n    if (blob.arrayBuffer) {\n        try {\n            const buf = await blob.arrayBuffer()\n            const bytes = new Uint8Array(buf)\n            let bin = \'\'\n            for (let i = 0; i < bytes.byteLength; i++) bin += String.fromCharCode(bytes[i])\n            return btoa(bin)\n        } catch (e) { /* fall through */ }\n    }\n    return new Promise((resolve, reject) => {\n        const reader = new FileReader()\n        reader.onload = () => {\n            const dataUrl = String(reader.result || \'\')\n            const idx = dataUrl.indexOf(\',\')\n            resolve(idx >= 0 ? dataUrl.slice(idx + 1) : dataUrl)\n        }\n        reader.onerror = () => reject(reader.error)\n        reader.readAsDataURL(blob)\n    })\n}\n\nfunction onBeforeUpload({ file }) {\n    const allowed = [\'png\', \'jpeg\', \'jpg\', \'gif\', \'svg\', \'webp\', \'ico\']\n    const suffix = (file.name || \'\').split(\'.\').pop().toLowerCase()\n    if (!allowed.includes(suffix)) {\n        $message.warning(\'仅支持 png/jpeg/gif/svg/webp/ico 图片\')\n        return false\n    }\n    if (file.size > 2 * 1024 * 1024) {\n        $message.warning(\'图标不能超过 2MB\')\n        return false\n    }\n    return true\n}\n\nasync function onUploadChange({ file, fileList }) {\n    // multiple 模式下 change 会逐个触发，仅处理当前新增的 pending 文件\n    const target = file?.file\n    if (!target) return\n    try {\n        const base64 = await readFileAsBase64(target)\n        const res = await $common.postJson(\'/api/ai/upload-base64\', {\n            fileName: file.name || \'icon.png\',\n            base64\n        })\n        if (res.data && res.data.state === \'SUCCESS\') {\n            const name = (file.name || \'icon\').replace(/\\.\\w+$/, \'\')\n            const saveRes = await $common.post(\'/system/menu-icon/save\', {\n                iconName: name,\n                iconValue: res.data.url,\n                iconDesc: \'用户上传\'\n            })\n            if (saveRes.code === 200) {\n                $message.success(\'已上传：\' + name)\n            } else {\n                $message.error(\'保存失败：\' + (saveRes.message || \'未知错误\'))\n            }\n        } else {\n            $message.error(\'上传失败：\' + (res.data?.msg || res.message || \'未知错误\'))\n        }\n    } catch (e) {\n        $message.error(\'上传失败：\' + (e.message || \'未知错误\'))\n    }\n    // 记录本次已处理，全部处理完后再统一刷新列表\n    processedIds.value.add(file.id)\n    const pending = (fileList || []).filter(f => f.status === \'pending\')\n    if (pending.every(f => processedIds.value.has(f.id))) {\n        processedIds.value = new Set()\n        loadUploaded()\n        bumpIcons()\n    }\n}\n\nfunction onBeforeImport({ file }) {\n    if (file.size > 5 * 1024 * 1024) {\n        $message.warning(\'iconfont 文件不能超过 5MB\')\n        return false\n    }\n    return true\n}\n\nasync function onIconfontImport({ file }) {\n    const f = file?.file\n    if (!f) return\n    const text = await readFileAsText(f)\n    const symbols = parseIconfontSymbols(text)\n    if (!symbols.length) {\n        $message.error(\'未解析到任何 symbol，请上传 iconfont「Symbol」模式导出的 iconfont.js / iconfont.svg\')\n        return\n    }\n    let ok = 0\n    const seen = new Set()\n    for (const s of symbols) {\n        if (seen.has(s.name)) continue\n        seen.add(s.name)\n        try {\n            const svg = `<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"${s.viewBox}\">${s.body}</svg>`\n            const saveRes = await $common.post(\'/system/menu-icon/save\', {\n                iconName: s.name,\n                iconValue: \'data:image/svg+xml;base64,\' + utf8ToBase64(svg),\n                iconDesc: \'iconfont 导入\'\n            })\n            if (saveRes.code === 200) ok++\n        } catch (e) { /* 单个失败跳过 */ }\n    }\n    if (ok) {\n        $message.success(`成功导入 ${ok} 个图标` + (ok < symbols.length ? `，${symbols.length - ok} 个跳过/失败` : \'\'))\n    } else {\n        $message.error(\'导入失败\')\n    }\n    loadUploaded()\n    bumpIcons()\n}\n\nfunction readFileAsText(blob) {\n    return new Promise((resolve, reject) => {\n        const reader = new FileReader()\n        reader.onload = () => resolve(String(reader.result || \'\'))\n        reader.onerror = () => reject(reader.error)\n        reader.readAsText(blob)\n    })\n}\n\nfunction parseIconfontSymbols(text) {\n    const symbols = []\n    const re = /<symbol\\s+([^>]*)>([\\s\\S]*?)<\\/symbol>/g\n    let m\n    while ((m = re.exec(text))) {\n        const attrs = parseAttrs(m[1])\n        const name = String(attrs.id || \'\').replace(/^icon-/, \'\')\n        if (!name) continue\n        symbols.push({\n            name,\n            body: m[2],\n            viewBox: attrs.viewBox || \'0 0 1024 1024\'\n        })\n    }\n    return symbols\n}\n\nfunction parseAttrs(str) {\n    const attrs = {}\n    const re = /([\\w-]+)=[\"\']([^\"\']*)[\"\']/g\n    let m\n    while ((m = re.exec(str))) attrs[m[1]] = m[2]\n    return attrs\n}\n\nfunction utf8ToBase64(str) {\n    const bytes = new TextEncoder().encode(str)\n    let bin = \'\'\n    for (const b of bytes) bin += String.fromCharCode(b)\n    return btoa(bin)\n}\n\nfunction copyValue(item) {\n    copyText(item.iconValue)\n}\n\nfunction copyText(text) {\n    navigator.clipboard?.writeText(text).then(() => {\n        $message.success(\'已复制：\' + text)\n    }).catch(() => {\n        const ta = document.createElement(\'textarea\')\n        ta.value = text\n        document.body.appendChild(ta)\n        ta.select()\n        document.execCommand(\'copy\')\n        document.body.removeChild(ta)\n        $message.success(\'已复制\')\n    })\n}\n\nfunction removeIcon(item) {\n    $dialog.create({\n        title: \'确认删除\',\n        content: `确定删除图标「${item.iconName || item.id}」吗？已使用该图标的菜单不受影响。`,\n        positiveText: \'删