('9a3841cf-a768-433e-919a-df159dd42688','29d82244-d928-11ee-9675-c2b02332sd','openapi-api-auth','<template>\n  <div class=\"mb-list\">\n    <div class=\"mb-search\">\n      <n-space>\n        <n-select v-model:value=\"currentAppId\" :options=\"appOptions\" placeholder=\"选择应用\" clearable style=\"width:280px\" @update:value=\"onAppChange\" />\n        <n-input v-model:value=\"filterApiPath\" placeholder=\"检索接口路径\" clearable style=\"width:200px\" @keyup.enter=\"doSearch\" />\n        <n-input v-model:value=\"filterApiName\" placeholder=\"检索接口名称\" clearable style=\"width:200px\" @keyup.enter=\"doSearch\" />\n        <n-button type=\"primary\" @click=\"doSearch\">\n          <mb-icon icon=\"Search\" /> 查询\n        </n-button>\n        <n-button @click=\"doReset\">\n          <mb-icon icon=\"Refresh\" /> 重置\n        </n-button>\n      </n-space>\n    </div>\n    <div class=\"mb-toolbar\">\n      <n-button type=\"primary\" :disabled=\"!currentAppId\" @click=\"handleBatchAdd\">\n        <mb-icon icon=\"AddOutline\" /> 批量添加\n      </n-button>\n    </div>\n    <div class=\"mb-table\">\n      <mb-table ref=\"table\" v-bind=\"tableOptions\" />\n    </div>\n\n    <mb-modal ref=\"batchDialog\" title=\"批量添加接口授权\" width=\"780px\" @confirm=\"saveBatch($event)\">\n      <div style=\"margin-bottom: 12px; display: flex; gap: 12px; align-items: center; flex-wrap: wrap\">\n        <n-input v-model:value=\"batchSearchKeyword\" placeholder=\"快速检索：路径 / 名称 / 分组\" clearable style=\"flex:1; min-width:260px\">\n          <template #prefix>\n            <mb-icon icon=\"Search\" />\n          </template>\n        </n-input>\n        <span style=\"color:#999; font-size:12px\">已选 <b style=\"color:#18a058\">{{ batchSelectedCount }}</b> 个接口</span>\n      </div>\n\n      <div style=\"margin-bottom: 12px; display: flex; gap: 12px; align-items: center; flex-wrap: wrap\">\n        <n-checkbox v-model:checked=\"batchRateLimitSwitch\" @update:checked=\"(v) => !v && (batchRateLimit = null)\">\n          自定义统一限流（次）\n        </n-checkbox>\n        <n-input-number v-model:value=\"batchRateLimit\" :disabled=\"!batchRateLimitSwitch\" placeholder=\"留空=继承应用配置\" :min=\"1\" style=\"width: 160px\" />\n        <n-divider vertical />\n        <span style=\"color:#999; font-size:12px\">统一窗口（秒）</span>\n        <n-input-number v-model:value=\"batchRateDuration\" placeholder=\"默认 60\" :min=\"1\" style=\"width: 160px\" />\n      </div>\n\n      <div style=\"border: 1px solid #e6e8eb; border-radius: 4px; max-height: 420px; overflow: auto\">\n        <n-tree\n          block-line\n          selectable\n          checkable\n          cascade\n          :data=\"filteredCatalogTreeChildren\"\n          :pattern=\"batchSearchKeyword\"\n          :render-switcher-icon=\"renderSwitcherIcon\"\n          :render-label=\"renderTreeLabel\"\n          :key-field=\"\'key\'\"\n          :children-field=\"\'children\'\"\n          :label-field=\"\'name\'\"\n          :default-expand-all=\"!batchSearchKeyword\"\n          v-model:checked-keys=\"batchCheckedKeys\"\n          v-model:expanded-keys=\"batchExpandedKeys\"\n          @update:checked=\"onBatchCheckedChange\"\n        />\n        <div v-if=\"filteredCatalogTree.children && filteredCatalogTree.children.length === 0\" style=\"text-align: center; padding: 60px; color: #999\">\n          暂无可授权的后端接口\n        </div>\n      </div>\n\n      <n-alert v-if=\"batchSelectedCount > 0\" type=\"info\" :show-icon=\"false\" style=\"margin-top: 12px\">\n        将为 <b>{{ currentAppName }}</b> 授权以下接口：\n        <div style=\"margin-top: 4px; max-height: 100px; overflow-y: auto; font-size: 12px\">\n          <div v-for=\"row in batchSelectedLeaves\" :key=\"row.path + row.method\" style=\"color:#555; padding: 2px 0\">\n            · <span style=\"color:#999\">[{{ row.method }}]</span> {{ row.displayName }} <span style=\"color:#bbb; font-size: 11px\">({{ row.path }})</span>\n          </div>\n        </div>\n      </n-alert>\n    </mb-modal>\n\n    <mb-modal ref=\"editDialog\" title=\"修改接口授权\" width=\"600px\" @confirm=\"saveEdit($event)\">\n      <n-form ref=\"editForm\" :model=\"editTemp\" label-placement=\"left\" label-width=\"100px\">\n        <n-form-item label=\"接口路径\">\n          <n-input :value=\"editTemp.api_path\" disabled />\n        </n-form-item>\n        <n-form-item label=\"HTTP方法\">\n          <n-input :value=\"editTemp.api_method\" disabled />\n        </n-form-item>\n        <n-form-item label=\"接口名称\">\n          <n-input v-model:value=\"editTemp.api_name\" placeholder=\"选填，便于识别\" />\n        </n-form-item>\n        <n-grid :cols=\"2\">\n          <n-gi>\n            <n-form-item label=\"限流次数\" path=\"rate_limit\">\n              <n-input-number v-model:value=\"editTemp.rate_limit\" :min=\"1\" placeholder=\"继承应用配置\" style=\"width:100%\" />\n            </n-form-item>\n          </n-gi>\n          <n-gi>\n            <n-form-item label=\"限流窗口(秒)\" path=\"rate_duration\">\n              <n-input-number v-model:value=\"editTemp.rate_duration\" :min=\"1\" placeholder=\"默认 60\" style=\"width:100%\" />\n            </n-form-item>\n          </n-gi>\n        </n-grid>\n        <n-form-item label=\"状态\" path=\"status\">\n          <n-switch v-model:value=\"editTemp.status\" :checked-value=\"1\" :unchecked-value=\"0\" />\n        </n-form-item>\n      </n-form>\n    </mb-modal>\n\n    <mb-modal ref=\"detailDialog\" :title=\"detailTitle\" width=\"760px\" :show-footer=\"false\">\n      <template v-if=\"detailData\">\n        <n-descriptions :column=\"2\" bordered size=\"small\" label-placement=\"left\">\n          <n-descriptions-item label=\"接口路径\">\n            <span style=\"font-family: monospace\">{{ detailData.apiPath }}</span>\n          </n-descriptions-item>\n          <n-descriptions-item label=\"请求方式\">\n            <n-tag size=\"small\" type=\"info\" :bordered=\"false\">{{ detailData.apiMethod }}</n-tag>\n          </n-descriptions-item>\n          <n-descriptions-item label=\"接口名称\">\n            {{ detailData.apiName || \'-\' }}\n          </n-descriptions-item>\n          <n-descriptions-item label=\"限流配置\">\n            {{ detailData.rateLimit ? detailData.rateLimit + \' 次 / \' + (detailData.rateDuration || 60) + \' 秒\' : \'继承应用配置\' }}\n          </n-descriptions-item>\n          <n-descriptions-item label=\"状态\">\n            <n-tag size=\"small\" :type=\"detailData.status === 1 ? \'success\' : \'error\'\" :bordered=\"false\">\n              {{ detailData.status === 1 ? \'启用\' : \'停用\' }}\n            </n-tag>\n          </n-descriptions-item>\n        </n-descriptions>\n\n        <div v-if=\"detailData.description\" style=\"margin-top: 16px\">\n          <div style=\"font-weight: 600; margin-bottom: 6px; color:#333\">接口说明</div>\n          <div style=\"color:#555; line-height:1.7\">{{ detailData.description }}</div>\n        </div>\n\n        <template v-if=\"detailData.parameters && detailData.parameters.length > 0\">\n          <div style=\"font-weight: 600; margin: 16px 0 6px; color:#333\">请求参数</div>\n          <n-data-table\n            :columns=\"paramColumns\"\n            :data=\"detailData.parameters\"\n            :pagination=\"false\"\n            :bordered=\"true\"\n            size=\"small\"\n          />\n        </template>\n\n        <div v-if=\"detailData.requestBody\" style=\"margin-top: 16px\">\n          <div style=\"font-weight: 600; margin-bottom: 6px; color:#333\">请求体（JSON）</div>\n          <pre class=\"doc-code\"><code>{{ detailData.requestBody }}</code></pre>\n        </div>\n\n        <div v-if=\"detailData.responseBody\" style=\"margin-top: 16px\">\n          <div style=\"font-weight: 600; margin-bottom: 6px; color:#333\">返回值（JSON）</div>\n          <pre class=\"doc-code\"><code>{{ detailData.responseBody }}</code></pre>\n        </div>\n\n        <n-empty v-if=\"!detailData.parameters.length && !detailData.requestBody && !detailData.responseBody && !detailData.description\" description=\"该接口未配置文档说明\" style=\"margin-top: 24px\" />\n      </template>\n    </mb-modal>\n  </div>\n</template>\n\n<style scoped>\n.search-row { padding: 8px 0; }\n.doc-code {\n  background: #f6f8fa;\n  border: 1px solid #e6e8eb;\n  border-radius: 4px;\n  padding: 10px 12px;\n  margin: 0;\n  overflow: auto;\n  max-height: 320px;\n  font-size: 12px;\n  line-height: 1.6;\n  font-family: \'JetBrains Mono\', Consolas, monospace;\n  color: #24292f;\n  white-space: pre;\n}\n</style>\n\n<script setup>\nimport { ref, reactive, computed, nextTick, onMounted, h } from \'vue\'\nimport { NIcon, NCheckbox, NTag } from \'naive-ui\'\n\nconst appOptions = ref([])\nconst currentAppId = ref(null)\nconst filterApiPath = ref(\'\')\nconst filterApiName = ref(\'\')\n\nconst currentAppName = computed(() => {\n  const item = appOptions.value.find(it => it.value === currentAppId.value)\n  return item ? item.label : \'(未选择)\'\n})\n\nconst tableOptions = reactive({\n  id: \'open-app-api\',\n  url: \'/system/open/app/api/list\',\n  page: true,\n  where: {\n    appId: { value: \'\' },\n    apiPath: { value: \'\' },\n    apiName: { value: \'\' }\n  },\n  cols: [\n    { field: \'apiPath\', label: \'接口路径\', width: 260 },\n    { field: \'apiName\', label: \'接口名称\', width: 200 },\n    { field: \'apiMethod\', label: \'方法\', width: 70 },\n    { field: \'rateLimit\', label: \'限流次数\', width: 80 },\n    { field: \'rateDuration\', label: \'窗口(秒)\', width: 90 },\n    { field: \'status\', label: \'状态\', type: \'switch\', width: 80,\n      change: (row) => updateApi(row) },\n    {\n      label: \'操作\', type: \'buttons\', width: 200, fixed: \'right\',\n      buttons: [\n        { label: \'详情\', link: true, click: (row) => handleDetail(row) },\n        { label: \'修改\', link: true, click: (row) => handleEdit(row) },\n        { label: \'删除\', link: true, click: (row) => {\n          $common.handleDelete({ url: \'/system/open/app/api/delete\', id: row.id, done: () => reloadTable() })\n        }}\n      ]\n    }\n  ]\n})\n\nconst table = ref()\nconst batchDialog = ref()\nconst editDialog = ref()\nconst editForm = ref()\nconst detailDialog = ref()\nconst detailData = ref(null)\nconst detailTitle = ref(\'接口文档\')\n\nconst apiCatalogTree = ref({ name: \'api\', children: [] })\nconst batchSearchKeyword = ref(\'\')\nconst batchCheckedKeys = ref([])\nconst batchExpandedKeys = ref([])\nconst batchRateLimitSwitch = ref(false)\nconst batchRateLimit = ref(null)\nconst batchRateDuration = ref(60)\n\nconst editTemp = ref(getEditTemp())\n\nconst flatAllLeaves = ref([])\n\nconst filteredCatalogTree = computed(() => {\n  if (!batchSearchKeyword.value || !batchSearchKeyword.value.trim()) {\n    return apiCatalogTree.value\n  }\n  return filterTree(apiCatalogTree.value, batchSearchKeyword.value.trim().toLowerCase()) || { name: \'api\', children: [] }\n})\n\nconst filteredCatalogTreeChildren = computed(() => {\n  const t = filteredCatalogTree.value\n  return (t && t.children) || []\n})\n\nconst batchSelectedLeaves = computed(() => {\n  const set = new Set(batchCheckedKeys.value)\n  return flatAllLeaves.value.filter(l => set.has(l.key))\n})\n\nconst batchSelectedCount = computed(() => batchSelectedLeaves.value.length)\n\nfunction getEditTemp() {\n  return { id: \'\', app_id: \'\', api_path: \'\', api_name: \'\', api_method: \'\', rate_limit: null, rate_duration: 60, status: 1 }\n}\n\nfunction reloadTable() {\n  tableOptions.where.appId = currentAppId.value || \'\'\n  tableOptions.where.apiPath = filterApiPath.value || \'\'\n  tableOptions.where.apiName = filterApiName.value || \'\'\n  if (table.value) table.value.reload()\n}\n\nfunction onAppChange() {\n  reloadTable()\n}\n\nfunction doSearch() {\n  reloadTable()\n}\n\nfunction doReset() {\n  filterApiPath.value = \'\'\n  filterApiName.value = \'\'\n  reloadTable()\n}\n\nfunction loadApps() {\n  $common.post(\'/system/open/app/list\', {}).then(res => {\n    const list = res?.data?.list || []\n    appOptions.value = list.map(item => ({\n      label: `${item.appName} (${item.appKey})`,\n      value: item.id\n    }))\n  })\n}\n\nfunction loadCatalog() {\n  $common.get(\'/system/open/app/api/catalog\', { app_id: currentAppId.value }).then(res => {\n    const data = Array.isArray(res) ? res : (res?.data || { children: [] })\n    apiCatalogTree.value = data && data.children ? data : { name: \'api\', children: [] }\n    flatAllLeaves.value = collectLeaves(apiCatalogTree.value)\n  })\n}\n\nfunction collectLeaves(node, parent) {\n  const out = []\n  if (!node) return out\n  if (node.type === \'api\' && node.path) {\n    const groupPath = parent || \'\'\n    out.push({\n      key: node.key,\n      path: node.path,\n      method: node.method,\n      name: node.name,\n      group: groupPath,\n      displayName: (groupPath ? groupPath + \'/\' : \'\') + (node.name || \'\')\n    })\n    return out\n  }\n  const newParent = parent ? (node.name ? parent + \'/\' + node.name : parent) : (node.name || \'\')\n  if (node.children) {\n    for (const c of node.children) {\n      out.push(...collectLeaves(c, newParent))\n    }\n  }\n  return out\n}\n\nfunction filterTree(node, kw) {\n  if (!node) return null\n  if (node.type === \'api\' && node.path) {\n    const text = (node.path + \' \' + node.method + \' \' + (node.name || \'\')).toLowerCase()\n    return text.includes(kw) ? node : null\n  }\n  if (!node.children) return null\n  const kept = []\n  for (const c of node.children) {\n    const f = filterTree(c, kw)\n    if (f) kept.push(f)\n  }\n  if (kept.length === 0 && node.name && node.name.toLowerCase().includes(kw)) {\n    return { ...node, children: kept }\n  }\n  return kept.length > 0 ? { ...node, children: kept } : null\n}\n\nfunction renderSwitcherIcon() {\n  return h(NIcon, null, { default: () => h(\'span\', \'▶\') })\n}\n\nfunction renderTreeLabel(info) {\n  const node = info.option || info.node\n  if (!node) return null\n  if (node.type === \'api\') {\n    return h(\'span\', { style: \'display:inline-flex; align-items:center; gap:8px;\' }, [\n      h(NTag, { size: \'small\', type: \'default\', bordered: false, round: true }, { default: () => node.method || \'GET\' }),\n      h(\'span\', { style: \'color:#0066cc; font-family:monospace;\' }, node.path),\n      h(\'span\', { style: \'color:#666; font-size:12px;\' }, node.name || \'\')\n    ])\n  }\n  return h(\'span\', { style: \'font-weight:500; color:#333\' }, node.name)\n}\n\nfunction onBatchCheckedChange(keys, options) {\n  batchCheckedKeys.value = keys\n}\n\nfunction handleBatchAdd() {\n  batchSearchKeyword.value = \'\'\n  batchCheckedKeys.value = []\n  batchExpandedKeys.value = []\n  batchRateLimit.value = null\n  batchRateLimitSwitch.value = false\n  batchRateDuration.value = 60\n  loadCatalog()\n  batchDialog.value.show()\n}\n\nfunction saveBatch(d) {\n  const leaves = batchSelectedLeaves.value\n  if (leaves.length === 0) {\n    $message.warning(\'请至少选择一个接口\')\n    d.hideLoading()\n    setTimeout(() => batchDialog.value.show(), 0)\n    return\n  }\n  d.loading()\n  const items = leaves.map(leaf => ({\n    api_path: leaf.path,\n    api_name: leaf.displayName,\n    api_method: leaf.method,\n    status: 1,\n    rate_limit: batchRateLimitSwitch.value ? batchRateLimit.value : null,\n    rate_duration: batchRateDuration.value\n  }))\n  $common.postJson(\'/system/open/app/api/save-batch\', {\n    app_id: currentAppId.value,\n    items: items\n  }).then(res => {\n    d.hideLoading()\n    batchDialog.value.hide()\n    const data = res?.data || {}\n    $message.success(`成功：新增 ${data.added || 0} 条${data.skipped ? `，跳过 ${data.skipped} 条（已存在）` : \'\'}`)\n    reloadTable()\n  }).catch(() => d.hideLoading())\n}\n\nconst paramColumns = [\n  { title: \'参数名\', key: \'name\', width: 160 },\n  { title: \'类型\', key: \'dataType\', width: 100 },\n  { title: \'必填\', key: \'required\', width: 70, render: (row) => h(NTag, { size: \'small\', type: row.required ? \'error\' : \'default\', bordered: false }, { default: () => row.required ? \'是\' : \'否\' }) },\n  { title: \'默认值\', key: \'defaultValue\', width: 110, render: (row) => row.defaultValue != null ? String(row.defaultValue) : \'-\' },\n  { title: \'说明\', key: \'description\', render: (row) => row.description || \'-\' }\n]\n\nfunction handleDetail(row) {\n  detailData.value = null\n  detailTitle.value = `接口文档：${row.apiPath || \'\'}`\n  detailDialog.value.show()\n  $common.get(\'/system/open/app/api/detail\', {\n    app_id: row.appId || currentAppId.value,\n    api_path: row.apiPath,\n    api_method: row.apiMethod\n  }).then(res => {\n    const data = res?.data || {}\n    if (data.found === false) {\n      detailData.value = {\n        apiPath: row.apiPath,\n        apiMethod: row.apiMethod,\n        apiName: row.apiName || \'\',\n        rateLimit: row.rateLimit,\n        rateDuration: row.rateDuration,\n        status: row.status,\n        description: \'\',\n        parameters: [],\n        requestBody: \'\',\n        responseBody: \'\'\n      }\n      $message.warning(\'未找到该接口授权记录\')\n      return\n    }\n    detailData.value = data\n  })\n}\n\nfunction handleEdit(row) {  editTemp.value = {\n    id: row.id,\n    app_id: row.appId,\n    api_path: row.apiPath,\n    api_name: row.apiName,\n    api_method: row.apiMethod,\n    rate_limit: row.rateLimit,\n    rate_duration: row.rateDuration,\n    status: row.status\n  }\n  editDialog.value.show()\n  nextTick(() => editForm.value && editForm.value.restoreValidation && editForm.value.restoreValidation())\n}\n\nfunction saveEdit(d) {\n  d.loading()\n  $common.post(\'/system/open/app/api/save\', {\n    id: editTemp.value.id,\n    app_id: editTemp.value.app_id,\n    api_path: editTemp.value.api_path,\n    api_name: editTemp.value.api_name,\n    api_method: editTemp.value.api_method,\n    rate_limit: editTemp.value.rate_limit,\n    rate_duration: editTemp.value.rate_duration,\n    status: editTemp.value.status\n  }).then(() => {\n    d.hideLoading()\n    editDialog.value.hide()\n    $message.success(\'修改成功\')\n    reloadTable()\n  }).catch(() => d.hideLoading())\n}\n\nfunction updateApi(row) {\n  $common.post(\'/system/open/app/api/save\', {\n    id: row.id,\n    app_id: row.appId,\n    api_path: row.apiPath,\n    api_name: row.apiName,\n    api_method: row.apiMethod,\n    rate_limit: row.rateLimit,\n    rate_duration: row.rateDuration,\n    status: row.status\n  })\n}\n\nonMounted(() => {\n  loadApps()\n})\n</script>\n','/* Analyzed bindings: {\n  \"ref\": \"setup-const\",\n  \"reactive\": \"setup-const\",\n  \"computed\": \"setup-const\",\n  \"nextTick\": \"setup-const\",\n  \"onMounted\": \"setup-const\",\n  \"h\": \"setup-const\",\n  \"NIcon\": \"setup-maybe-ref\",\n  \"NCheckbox\": \"setup-maybe-ref\",\n  \"NTag\": \"setup-maybe-ref\",\n  \"appOptions\": \"setup-ref\",\n  \"currentAppId\": \"setup-ref\",\n  \"filterApiPath\": \"setup-ref\",\n  \"filterApiName\": \"setup-ref\",\n  \"currentAppName\": \"setup-ref\",\n  \"tableOptions\": \"setup-reactive-const\",\n  \"table\": \"setup-ref\",\n  \"batchDialog\": \"setup-ref\",\n  \"editDialog\": \"setup-ref\",\n  \"editForm\": \"setup-ref\",\n  \"detailDialog\": \"setup-ref\",\n  \"detailData\": \"setup-ref\",\n  \"detailTitle\": \"setup-ref\",\n  \"apiCatalogTree\": \"setup-ref\",\n  \"batchSearchKeyword\": \"setup-ref\",\n  \"batchCheckedKeys\": \"setup-ref\",\n  \"batchExpandedKeys\": \"setup-ref\",\n  \"batchRateLimitSwitch\": \"setup-ref\",\n  \"batchRateLimit\": \"setup-ref\",\n  \"batchRateDuration\": \"setup-ref\",\n  \"editTemp\": \"setup-ref\",\n  \"flatAllLeaves\": \"setup-ref\",\n  \"filteredCatalogTree\": \"setup-ref\",\n  \"filteredCatalogTreeChildren\": \"setup-ref\",\n  \"batchSelectedLeaves\": \"setup-ref\",\n  \"batchSelectedCount\": \"setup-ref\",\n  \"getEditTemp\": \"setup-const\",\n  \"reloadTable\": \"setup-const\",\n  \"onAppChange\": \"setup-const\",\n  \"doSearch\": \"setup-const\",\n  \"doReset\": \"setup-const\",\n  \"loadApps\": \"setup-const\",\n  \"loadCatalog\": \"setup-const\",\n  \"collectLeaves\": \"setup-const\",\n  \"filterTree\": \"setup-const\",\n