('bc38eb5038ce44aab4bd586fb32d79bb','fc061efbc39948d59aafc3905591c935','user-list','<style scoped>\n.left {\n    width: calc(20% - 20px);\n    margin-right: 20px;\n    float: left;\n}\n\n.right {\n    width: 80%;\n    height: 100%;\n    float: right;\n}\n\n.app-container {\n    width: 100%;\n    height: 100%;\n}\n</style>\n\n<template>\n    <div class=\"app-container\">\n        <div class=\"left\">\n            <mb-tree\n                url=\"/system/office/tree\"\n                v-model=\"tableOptions.where.officeId\"\n                :expand=\"false\"\n                search\n                search-width=\"100%\"\n                checkable\n                :checked=\"false\"\n                @check-change=\"checkChange\"\n            />\n        </div>\n        <div class=\"right\">\n            <div class=\"mb-list\">\n                <div class=\"mb-search\">\n                    <mb-search :where=\"tableOptions.where\" @search=\"reloadTable\">\n                        <template #buttons>\n                            <n-button type=\"primary\" @click=\"table.exportExcel({ fileName: \'用户数据\' })\">\n                                <mb-icon icon=\"DownloadOutline\" />\n                                导出\n                            </n-button>\n                        </template>\n                    </mb-search>\n                </div>\n\n                <div class=\"mb-toolbar\">\n                    <n-button :size=\"$global.uiSize.value\"  v-permission=\"\'user:save\'\" type=\"primary\" @click=\"handleCreate\">\n                        <mb-icon icon=\"AddOutline\" />\n                        添加用户\n                    </n-button>\n                    <!--          <mb-button v-permission=\"\'user:delete\'\" plain :request-url=\"\'/system/user/delete\'\" :btn-type=\"\'delete\'\" :request-data=\"{ id: ids }\" :after-handler=\"reloadTable\" />-->\n                    <!--          <mb-upload-file ref=\"importUserRef\" action=\"/system/user/import/preview\" label=