            autocomplete: \"new-password\"\n              }, null, 8 /* PROPS */, [\"value\"])\n            ]),\n            _: 1 /* STABLE */\n          }),\n          _createVNode(_component_n_form_item_gi, {\n            span: 12,\n            label: \"密码\",\n            path: \"password\"\n          }, {\n            default: _withCtx(() => [\n              _createVNode(_component_n_input, {\n                value: temp.value.password,\n                \"onUpdate:value\": _cache[1] || (_cache[1] = $event => ((temp.value.password) = $event)),\n                type: \"password\",\n                autocomplete: \"new-password\"\n              }, null, 8 /* PROPS */, [\"value\"])\n            ]),\n            _: 1 /* STABLE */\n          })\n        ]),\n        _: 1 /* STABLE */\n      }),\n      _createVNode(_component_n_grid, {\n        cols: 24,\n        \"x-gap\": 24\n      }, {\n        default: _withCtx(() => [\n          _createVNode(_component_n_form_item_gi, {\n            span: 12,\n            label: \"姓名/昵称\",\n            path: \"name\"\n          }, {\n            default: _withCtx(() => [\n              _createVNode(_component_n_input, {\n                value: temp.value.name,\n                \"onUpdate:value\": _cache[2] || (_cache[2] = $event => ((temp.value.name) = $event)),\n                autocomplete: \"new-password\"\n              }, null, 8 /* PROPS */, [\"value\"])\n            ]),\n            _: 1 /* STABLE */\n          }),\n          _createVNode(_component_n_form_item_gi, {\n            span: 12,\n            label: \"手机号\",\n            path: \"phone\"\n          }, {\n            default: _withCtx(() => [\n              _createVNode(_component_n_input, {\n                value: temp.value.phone,\n                \"onUpdate:value\": _cache[3] || (_cache[3] = $event => ((temp.value.phone) = $event))\n              }, null, 8 /* PROPS */, [\"value\"])\n            ]),\n            _: 1 /* STABLE */\n          })\n        ]),\n       